import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { backendRoot } from './sourceScan';

/**
 * Mr OneHook's OpenAPI (generated by OneHookBackend from packages/api-models/model/smithy/mr-onehook.smithy)
 * and a small validator for response bodies.
 *
 * OneHookBackend gitignores its build output and CI checks out only this repo, so the contract tests read a
 * byte-for-byte copy kept next to this file. When the sibling OneHookBackend build is present (local
 * development), a test requires the copy to equal it; refresh it with
 *   cp ../../OneHookBackend/packages/api-models/build/smithy/source/openapi-mr-onehook/MrOneHookService.openapi.json \
 *      src/__tests__/contract/
 */

export interface OpenApiSchema {
  $ref?: string;
  type?: string;
  properties?: Record<string, OpenApiSchema>;
  required?: string[];
  items?: OpenApiSchema;
  enum?: unknown[];
  minLength?: number;
  maxLength?: number;
  minItems?: number;
  maxItems?: number;
  minimum?: number;
  maximum?: number;
  [keyword: string]: unknown;
}

export interface OpenApiOperation {
  operationId: string;
  method: string;
  path: string;
  /** `[]` for an operation without auth; absent means the document default (Bearer). */
  security?: unknown[];
  responses: Record<string, { content?: Record<string, { schema: OpenApiSchema }> }>;
}

export interface OpenApiDocument {
  paths: Record<string, Record<string, Omit<OpenApiOperation, 'method' | 'path'>>>;
  components: { schemas: Record<string, OpenApiSchema> };
}

export const VENDORED_OPENAPI_PATH = path.join(backendRoot(), 'src/__tests__/contract/MrOneHookService.openapi.json');
export const SIBLING_OPENAPI_PATH = path.resolve(
  backendRoot(), '../../OneHookBackend/packages/api-models/build/smithy/source/openapi-mr-onehook/MrOneHookService.openapi.json');

export function loadOpenApi(file = VENDORED_OPENAPI_PATH): OpenApiDocument {
  return JSON.parse(readFileSync(file, 'utf8')) as OpenApiDocument;
}

export function siblingOpenApiPresent(): boolean {
  return existsSync(SIBLING_OPENAPI_PATH);
}

export function openApiOperations(doc: OpenApiDocument): OpenApiOperation[] {
  const ops: OpenApiOperation[] = [];
  for (const [p, methods] of Object.entries(doc.paths)) {
    for (const [method, op] of Object.entries(methods)) ops.push({ ...op, method: method.toUpperCase(), path: p });
  }
  return ops;
}

function templateRegex(template: string): RegExp {
  const body = template.split(/\{[^}/]+\}/).map((s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('[^/]+');
  return new RegExp(`^${body}$`);
}

/** The operation serving `method concretePath`, if any. */
export function findOperation(doc: OpenApiDocument, method: string, concretePath: string): OpenApiOperation | undefined {
  return openApiOperations(doc).find((op) => op.method === method.toUpperCase() && templateRegex(op.path).test(concretePath));
}

const IGNORED_KEYWORDS = new Set(['description', 'format', 'title', 'example']);
const HANDLED_KEYWORDS = new Set([
  '$ref', 'type', 'properties', 'required', 'items', 'enum', 'minLength', 'maxLength', 'minItems', 'maxItems', 'minimum', 'maximum',
]);

/**
 * Errors of `value` against `schema` (empty when it conforms). Objects are closed: a property the schema
 * does not declare is an error, since Smithy structures have no open members. A keyword this validator does
 * not know is an error too, so a richer schema can never pass unchecked.
 */
export function validate(doc: OpenApiDocument, schema: OpenApiSchema, value: unknown, at = '$'): string[] {
  for (const keyword of Object.keys(schema)) {
    if (!HANDLED_KEYWORDS.has(keyword) && !IGNORED_KEYWORDS.has(keyword)) return [`${at}: schema keyword \`${keyword}\` is not supported by the contract validator`];
  }
  if (schema.$ref) {
    const name = schema.$ref.replace('#/components/schemas/', '');
    const target = doc.components.schemas[name];
    return target ? validate(doc, target, value, at) : [`${at}: unknown $ref ${schema.$ref}`];
  }
  const errors: string[] = [];
  if (schema.enum && !schema.enum.includes(value)) errors.push(`${at}: ${JSON.stringify(value)} is not one of ${JSON.stringify(schema.enum)}`);
  switch (schema.type) {
    case 'object': {
      if (typeof value !== 'object' || value === null || Array.isArray(value)) return [...errors, `${at}: expected an object, got ${JSON.stringify(value)}`];
      const record = value as Record<string, unknown>;
      const properties = schema.properties ?? {};
      for (const key of schema.required ?? []) if (!(key in record)) errors.push(`${at}.${key}: required but missing`);
      for (const [key, v] of Object.entries(record)) {
        const propertySchema = properties[key];
        if (!propertySchema) errors.push(`${at}.${key}: not declared in the contract`);
        else errors.push(...validate(doc, propertySchema, v, `${at}.${key}`));
      }
      break;
    }
    case 'array': {
      if (!Array.isArray(value)) return [...errors, `${at}: expected an array`];
      if (schema.minItems !== undefined && value.length < schema.minItems) errors.push(`${at}: fewer than ${schema.minItems} items`);
      if (schema.maxItems !== undefined && value.length > schema.maxItems) errors.push(`${at}: more than ${schema.maxItems} items`);
      if (schema.items) value.forEach((item, i) => errors.push(...validate(doc, schema.items!, item, `${at}[${i}]`)));
      break;
    }
    case 'string':
      if (typeof value !== 'string') return [...errors, `${at}: expected a string, got ${JSON.stringify(value)}`];
      if (schema.minLength !== undefined && value.length < schema.minLength) errors.push(`${at}: shorter than ${schema.minLength}`);
      if (schema.maxLength !== undefined && value.length > schema.maxLength) errors.push(`${at}: longer than ${schema.maxLength}`);
      break;
    case 'integer':
    case 'number':
      if (typeof value !== 'number' || (schema.type === 'integer' && !Number.isInteger(value))) {
        return [...errors, `${at}: expected ${schema.type === 'integer' ? 'an integer' : 'a number'}, got ${JSON.stringify(value)}`];
      }
      if (schema.minimum !== undefined && value < schema.minimum) errors.push(`${at}: below ${schema.minimum}`);
      if (schema.maximum !== undefined && value > schema.maximum) errors.push(`${at}: above ${schema.maximum}`);
      break;
    case 'boolean':
      if (typeof value !== 'boolean') errors.push(`${at}: expected a boolean, got ${JSON.stringify(value)}`);
      break;
    case undefined:
      if (!schema.enum) errors.push(`${at}: schema has no type`);
      break;
    default:
      errors.push(`${at}: schema type \`${schema.type}\` is not supported by the contract validator`);
  }
  return errors;
}

/**
 * Errors of one observed response against the operation's declared responses: the status must be declared,
 * a body-less response must have no body, and a JSON body must match the declared schema.
 */
export function checkResponse(
  doc: OpenApiDocument,
  op: OpenApiOperation,
  status: number,
  contentType: string | null,
  rawBody: string,
): string[] {
  const declared = op.responses[String(status)];
  if (!declared) return [`status ${status} is not declared (declared: ${Object.keys(op.responses).join(', ')}); body ${rawBody}`];
  const media = declared.content?.['application/json'];
  if (!media) return rawBody.length === 0 ? [] : [`status ${status} declares no body, got ${rawBody}`];
  if (!contentType?.includes('application/json')) return [`status ${status}: expected application/json, got ${contentType}`];
  let body: unknown;
  try {
    body = JSON.parse(rawBody);
  } catch {
    return [`status ${status}: body is not JSON: ${rawBody}`];
  }
  return validate(doc, media.schema, body).map((e) => `status ${status}: ${e}`);
}
